&lt;p&gt;&lt;strong&gt;Available Locations&lt;/strong&gt;: &lt;span class=&quot;collapsed-field-text&quot;&gt;Amsterdam, Netherlands, Lisbon, Portugal, Munich, Germany,&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h3 data-path-to-node=&quot;1&quot;&gt;&lt;strong data-path-to-node=&quot;1&quot; data-index-in-node=&quot;0&quot;&gt;Compensation&lt;/strong&gt;&lt;/h3&gt;
